#![allow(unused_macros, unused_variables)]
fn first(value: i32) { println!("first:{value}"); }
fn second(value: i32) { println!("second:{value}"); }
fn subject(x: i32, y: i32) -> i32 {
    let item = x;
    macro_rules! select { () => { item } }
    {
        let item = y;
        first(select!());
        second(item);
    }
    x
}
fn main() {
    for (x, y) in [(5, 11), (-2, 4), (7, -9)] {
        println!("result:{}", subject(x, y));
    }
}

